	static int index(String name) { for (int i = 0; i < ORDER.length; i++) if (ORDER[i].equals(name)) return i; return 0; }

	static void draw(net.minecraft.client.gui.GuiGraphicsExtractor g, String name, int x, int y) { draw(g, name, x, y, 1); }

	/** Draws icon {@code name} at (x, y) with each icon pixel scaled to {@code s} screen pixels. */
	static void draw(net.minecraft.client.gui.GuiGraphicsExtractor g, String name, int x, int y, int s) {
		int[] px = PX[index(name)];
		for (int k = 0; k < 100; k++) if (px[k] != 0) g.fill(x + (k % 10) * s, y + (k / 10) * s, x + (k % 10 + 1) * s, y + (k / 10 + 1) * s, px[k]);
	}
